import{db,roles,editable}from'../store.js';import{esc,heading,field,tag,note,button,link,icon,categoryLabel}from'../components/ui.js';
export function detail(t,module){const d=t.report||{};const canConfirm=db.role==='TL'&&t.tl===roles.TL[1]&&t.submitted&&t.status==='待完工確認';let action='';if(db.role==='MASTER'&&t.master===roles.MASTER[1]){if(t.status==='待確認')action=button('確認接單','accept');else if(t.status==='待處理')action=button('記錄到場','arrive');else if(editable(t))action=link(`填寫 ${t.reportKind} 現場記錄`,`edit/${t.id}`,'primary');}if(canConfirm)action=button('確認本次工作完成','confirm');return `<div class="detail-heading"><p>${esc(t.id)}</p><h1>${esc(t.customer)}</h1><div class="inline">${tag(t.status)}<span class="category">${esc(categoryLabel(t.category))}</span><span class="muted">${t.reportKind}</span></div></div>${note(t.scenario)}<section class="panel">${heading('現場資料')}${field('報告編號',t.cpNo?`CP-${t.cpNo}`:t.serviceReportNo?`SR-${t.serviceReportNo}`:'')}${field('合約編號',t.contractNo)}${field('服務地址',t.address)}${field('聯絡人',t.contact)}<div class="data-row"><span>聯絡電話</span><a href="tel:${esc(t.phone.replace(/[^+0-9]/g,''))}">${esc(t.phone)} ${icon('phone')}</a></div>${field('負責主管',t.tl)}${field('施工師傅',t.master)}${field('預約時間',t.schedule?.replace('T',' '))}${t.arrivedAt?field('本次到場時間',new Date(t.arrivedAt).toLocaleString('zh-HK')):''}<h3>工作內容</h3><p>${esc(t.desc)}</p></section>${module==='calls'&&['CS','CR','TL'].includes(db.role)?`<section class="panel">${heading('CALL 跟進')}<label>跟進內容<textarea id="callNote" placeholder="記錄已聯絡事項及下一步"></textarea></label><div class="inline">${button('儲存跟進','call-note','secondary')}${button('轉報價公共待辦','call-quote','secondary')}</div><p class="muted">不指定報價員，不自動結束 CALL 或建立成交。</p></section>`:''}${module==='dispatch'&&['TL','CR'].includes(db.role)&&t.status==='待分派'?`<section class="panel">${heading('安排本次工作')}${note(t.phaseReady?'演示前提已提供；不代表 C-04 已確認。':'本次階段供料前提未具備；不可用 MR 完成代替施工放行。')}<label>施工師傅<select id="master"><option>周師傅</option><option>吳師傅</option><option>黃師傅</option><option>梁師傅</option></select></label><label>預約日期及時間<input id="schedule" type="datetime-local" value="${esc(t.schedule)}"></label><button class="primary" data-action="dispatch" ${t.phaseReady?'':'disabled'}>安排師傅及時間</button></section>`:''}${t.report?`<section class="panel">${heading(t.reportKind+' 提交內容')}${field('服務日期',d.serviceDate)}${t.reportKind==='CP'?field('CP 編號',d.cpNo):''}${field('系統',d.srSystems)}${field('工作目的',d.srObjectives)}<h3>完成工作</h3><p>${esc(d.completedWork)}</p><h3>需跟進事項</h3><p>${esc(d.faultResult)}</p>${field('簽署人',d.signedBy)}${field('車資 (HKD)',d.transportFee||'0')}${d.receipt?`<p>Taxi 收據：${esc(d.receipt.name)}</p><img class="signature-preview" src="${d.receipt.url}" alt="Taxi 收據">`:''}${field('材料使用備註',d.materialUse||'無')}${d.signature?`<img class="signature-preview" src="${d.signature}" alt="客戶手寫簽名">`:note('未有簽名') }<div class="photo-grid">${(d.photos||[]).map(p=>`<img src="${p.url}" alt="${esc(p.name)}">`).join('')}</div>${d.quoteLines?.length?heading('需報價明細')+d.quoteLines.map(i=>`<p>${esc(i.name)}／${esc(i.model)}／${esc(i.location)}</p>`).join(''):''}</section>`:''}${canConfirm?`<section class="panel"><label>主管核對備註<textarea id="confirmNote" placeholder="選填：核對本次工作及單據"></textarea></label><p>確認只更新本次工作完成。M 整份保養、M+P 組合及票款各自跟進。</p></section>`:''}<section class="panel">${heading('處理進度')}<ol class="timeline">${t.records.map(r=>`<li><small>${esc(r.time)} · ${esc(r.actor)}</small><p>${esc(r.text)}</p></li>`).join('')}</ol></section>${t.category!=='P'?note('本次工作完成不代表整個 M／M+P 業務完成。整體完成條件仍待確認。'):''}${action?`<div class="actionbar">${action}</div>`:''}`;}
export function editor(t){let d=db.drafts[t.id]||t.report||{};return `${heading('填寫 '+t.reportKind)}<p class="muted">${esc(t.id)} · ${esc(t.customer)}</p>${note(t.reportKind==='CP'?'最終施工完成後提交 CP；不按每天施工自動完工。':'一次上門一份 SR；本次提交不結束整份保養。')}<form id="reportForm" novalidate>${t.reportKind==='CP'?`<section class="panel"><label>完工單 CP 編號 *<input name="cpNo" required value="${esc(d.cpNo||'')}" placeholder="回填紙單編號；不自動發號"></label><p class="muted">沿用 PC：須提供 Before、After 照片及含客戶簽署的 CP 正本影像。示例影像僅供模擬。</p></section>`:''}<section class="panel">${heading('服務與工作')}<label>服務日期 *<input name="serviceDate" type="date" required value="${esc(d.serviceDate||'2026-11-07')}"></label><label>系統 *<select name="srSystems" required>${['','CCTV','Access Control','Alarm','Others'].map(x=>`<option ${x===d.srSystems?'selected':''} value="${x}">${x||'請選擇系統'}</option>`).join('')}</select></label><label>工作目的 *<select name="srObjectives" required>${['','Routine Check','Fault Report','Emergency Call','Others'].map(x=>`<option ${x===d.srObjectives?'selected':''} value="${x}">${x||'請選擇目的'}</option>`).join('')}</select></label><label>已完成工作 *<textarea name="completedWork" required maxlength="3000" placeholder="記錄檢查、維修及測試結果">${esc(d.completedWork||'')}</textarea></label><label>需跟進事項 *<textarea name="faultResult" required placeholder="如沒有，請填「無」">${esc(d.faultResult||'')}</textarea></label><label>材料使用備註<textarea name="materialUse" placeholder="僅現場記錄，不執行領料或扣賬">${esc(d.materialUse||'')}</textarea></label></section><section class="panel">${heading('現場照片')}<p class="muted">可選取相片或使用相機。每張上限 2MB，最多 4 張；示例照片會明確標示。</p><label>照片用途<select id="photoKind"><option>Before</option><option>After</option>${t.reportKind==='CP'?'<option>CP正本</option>':''}</select></label><input id="photoInput" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" multiple><div id="photos" class="photo-grid"></div>${button('加入示例照片（模擬）','sample-photo','secondary')}</section><section class="panel">${heading('車資')}<label>交通方式<select name="transportMode">${['其他','Taxi'].map(x=>`<option ${x===d.transportMode?'selected':''}>${x}</option>`).join('')}</select></label><label>車資 (HKD)<input name="transportFee" type="number" min="0" max="99999" step="0.5" value="${esc(d.transportFee||'')}"></label><label>Taxi 收據（如選 Taxi 必須提供）<input id="receiptInput" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="receiptPreview"></div><p class="muted">依 SOURCE-038，Taxi 須收據；其他交通不強制。此處僅本機保存。</p></section><section class="panel">${heading('報價需求')}<label>是否需要報價 *<select name="needQuote" required><option value="">請選擇</option><option value="no" ${d.needQuote==='no'?'selected':''}>否</option><option value="yes" ${d.needQuote==='yes'?'selected':''}>是，轉公共報價待辦</option></select></label><div id="quoteLines"></div>${button('新增報價需求項目','add-line','secondary')}<p class="muted">需報價時填名稱／型號／位置，可多項；師傅不直接製作正式報價。</p>${note('即時維修特例：客戶現場同意、已維修及收款後，由報價組補記錄，不再接受／中單／收款。本期不實作後補交易，SR／CP 特例及現場款登記仍待確認 C-06/08。')}</section><section class="panel">${heading('客戶簽認')}<label>客戶簽署人姓名 *<input name="signedBy" required maxlength="80" value="${esc(d.signedBy||'')}"></label><p class="muted">請在下框手寫簽名；原型評審用途。</p><canvas id="signature" width="640" height="280" aria-label="客戶手寫簽名"></canvas>${button('清除簽名','clear-sign','secondary')}<p class="muted">客戶未能簽署時可儲存草稿；缺簽補件規則 C-08 待確認，不自動放行。</p></section><p id="formError" role="alert" class="error"></p><div class="actionbar">${button('儲存草稿','draft','secondary')}<button class="primary" type="submit">提交 ${t.reportKind}</button></div></form>`;}
